//! `tensor` generated by `mlirformat tblgen` (`tensor.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "tensor.gen.rs"]
mod tensor;

#[test]
fn tensor_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<tensor::Tensor>();
    common::Fixtures::check_dialect(&opt, "tensor");
}
